import json, pathlib
b={'start':1450,'end':1530,'decisions':{}}
def c(i,t,r): b['decisions'][str(i)]={'decision':'change','target':t,'reason':r}
c(1450,'هنا واحد صفر اثنان، أقدم تقريري! كل شيء هادئ الآن، ونحن نشعر بالملل!','تصحيح تعريف رقم النداء كمتكلم لا تسمية تقرير.')
c(1452,'هنا واحد واحد اثنان... لا نشاط هنا إطلاقًا. يبدو أنكم مدللون فحسب!','توحيد المخاطب الجمع وتعريف النداء.')
c(1453,'لا تقلقوا، ستنالون نصيبكم من الإثارة في النهاية... تابعوا!','piece of action نصيب من العمل القتالي لا حدث مجرد، وأمر للجمع.')
c(1454,'هنا واحد اثنان صفر، كل شيء هادئ، عدا بعض الاضطراب لدى وحوش الحراس...','تمييز Watchmen عن حراس البشر وحفظ رقم النداء.')
c(1456,'آه، هذا يفسر الأمر... شكرًا يا واحد ستة...','استعادة رقم النداء كاملًا؛ سقط one من الترجمة.')
c(1457,'حسنًا، يبدو أن الجميع قد أجاب... شكرًا يا رجال، واصلوا المراقبة وأبلغوا فورًا عن أي تغيرات.','accounted for تأكدوا من سلامة جميع النقاط وتلقي أجوبتها لا حساب أشخاص رياضيًا.')
c(1458,'واحد اثنان صفر، مفهوم!','Roger إقرار لا اسم شخص.')
c(1459,'واحد صفر اثنان، مفهوم!','Roger إقرار لا اسم شخص.')
c(1460,'مفهوم!','إقرار تلقي لاسلكي موحد.')
c(1462,'أرجوكم... إن كان أحد يسمعني... أرجوكم، ساعدوني!','نداء استغاثة عام لا مخاطب مفرد مجهول.')
c(1463,'ذهب أبي وعمي كوليا لطلب المساعدة... قبل أسبوع... ولم يعودا...','uncle Kolya عم الطفل لا عم أبيه.')
c(1466,'(تتكسر الألواح) آآه! النجدة!','Help صيحة استغاثة لا خبر يساعد.')
c(1467,'(يتحطم الزجاج، ويسقط شيء، ويزأر نوساليس، وينقطع الإرسال)','nosalis اسم الوحش لا الأنف؛ حفظ تسلسل المؤثرات.')
c(1470,'وماذا يلي في برنامجنا اليوم؟ آه، نعم، ما تنتظرونه جميعًا: الطقس!','فقرة البرنامج التالية لا خطوة عمل، وexpecting انتظار الجمهور.')
c(1473,'<single_phrase_mode><time=0>وكما أدركتم على الأرجح، يا مستمعي الأعزاء...<time=3280><time=3400>صارت لقمة عيش مذيع الطقس قاسية ومالحة بالعرق والدموع هذه الأيام...<time=8560><time=8760>فالاتصالات بعيدة عن المستوى المطلوب.<time=11540><time=11820>ومع ذلك، ثمة أسباب للتفاؤل الحذر!<time=15780><time=16280>قبل خمسة عشر عامًا لم يكن هناك أي بث، لا شيء على الإطلاق...<time=22100><time=22660>أما الآن، فتظهر محطات في أماكن لن تصدقوها!<time=27040><time=27500>قبل يومين فقط استقبلنا إرسالًا من جزر فارو، بالله عليكم!<time=33560><time=33920>ولست أكذب!<time=35200><time=35400>من يريد أن يلمسني الآن؟ هاهاها! على أي حال...<time=39600><time=39600>الخلاصة أن الحياة ما زالت قائمة على أرضنا العجوز، ويبدو أننا سنبقى عليها مدة أخرى في النهاية...<time=41600>','إصلاح leave much to be desired إلى ضعف الاتصالات وحفظ استعارة لقمة العيش ونبرة المذيع وجميع التوقيتات.')
c(1475,'وبالمناسبة، وصل شيء آخر للتو أيضًا! حان وقت تشغيل تسجيل قديم لدي هنا!','record تسجيل موسيقي لا سجل مكتوب.')
c(1476,'كان ذلك رائعًا... هذا التسجيل يؤثر فيّ كل مرة...','gets me تأثير عاطفي للأغنية لا لفت انتباه، وتوحيد التسجيل.')
c(1481,'ومجددًا، أهنئ نفسي على روعة اختيار اللحن! من العبقري؟ ماكس طبعًا! هاها!','صياغة مفاخرة المذيع بنفسه وpat on back دون حرفية.')
c(1484,'مايسترو، أسمعنا أفضل شارة موسيقية لديك، من فضلك!','jingle شارة إذاعية قصيرة لا أغنية كاملة.')
p1='بعد كل تلك السنين تحت الأرض، بدا هواء السطح نقيًا على نحو مذهل، مسكرًا... لكن فرحة الطاقم لم تكن بسببه. فقد أصبح لرحلتنا أخيرًا هدف واضح بفضل البث القادم من الملجأ الحكومي في الأورال.'
p2='طوال عشرين عامًا ظننا أن الحكومة والقيادة العسكرية العليا قد هلكتا. واتضح أنهما ما زالتا موجودتين... أين كانتا ونحن نفني بعضنا بعضًا في المترو؟'
p3='ستكون لدينا أسئلة كثيرة حين نبلغ يامانتو... إن بلغناه. يقول ميلر إن أنقاض بلادنا تحت سيطرة العدو، وعلينا أن نقاتل حتى نصل إلى هدفنا. فريق صغير في مواجهة جيوش الاحتلال... ما فرص نجاحنا؟ وفرص حصولنا على بعض الإجابات؟'
c(1486,'<tab>'+p1+'<br><br><tab>'+p2+'<br><br><tab>'+p3+'<br><br>','تصحيح المتكلم الجمع وتوحيد يامانتو وصياغة السرد، مع حفظ نسبة احتلال البلاد إلى قول ميلر لا حقيقة الراوي.')
c(1487,'<tab>'+p1+'<br><br>','مطابقة مقطع السرد لنظيره الكامل وتصحيح ضمير ما قضيناه تحت الأرض.')
c(1488,'<tab>'+p2+'<br><br>','مطابقة مقطع السرد الكامل وحفظ العتاب على غياب الحكومة والقيادة.')
c(1489,'<tab>'+p3+'<br><br>','توحيد يامانتو وحفظ الاحتمال ونسبة احتلال البلاد إلى ميلر وصياغة السؤالين.')
cp='لم يسر السكان برؤيتنا هنا إطلاقًا. يبدو أنهم أقاموا بعد الحرب طائفة تخشى التكنولوجيا، وتمكن زعيمها من محاصرتي في كنيستهم التي غمرت المياه نصفها. '
escape='لا أدري ما كانوا سيفعلونه بي لو أسروني، لكن امرأة تدعى كاتيا، كانوا يحتجزونها هنا، ساعدتني على '
ea=escape+'الإفلات منهم. ولحسن الحظ، لم أسقط أي ضحايا في أثناء ذلك. '
eb=escape+'الهرب. حدث تبادل لإطلاق النار، لكنني خرجت حيًا على الأقل. '
ec=escape+'الإفلات منهم. ولحسن الحظ، تجنبت سقوط عدد كبير من الضحايا في أثناء ذلك. '
k='حدثتني كاتيا عن مهندس يدعى كريست يختبئ من أتباع الطائفة في الميناء، وقد يساعدنا على إصلاح أورورا وعبور الجسر. يبدو أن الوقت مناسب لزيارته...'
for i,e,label in [(1490,ea,'تفادي الضحايا'),(1491,eb,'الهرب مع تبادل النار'),(1492,ec,'تفادي الخسائر المفرطة')]:
 c(i,'<tab>'+cp+e+k+'<br><br>','كاتيا هي الأسيرة لا المتعصبون، والكنيسة حوصرت على الراوي لا على نفسها؛ حفظ فرع '+label+' منفصلًا.')
c(1493,'<tab>'+cp.rstrip()+'<br><br>','الزعيم حاصر أرتيوم داخل الكنيسة، ولم يحاصر الكنيسة نفسها؛ إصلاح الفاعل والمفعول.')
for i,e,label in [(1494,ea,'تفادي الضحايا'),(1495,eb,'تبادل النار والهرب حيًا'),(1496,ec,'تفادي الخسائر المفرطة')]:
 c(i,'<tab>'+e.rstrip()+'<br><br>','تصحيح أسْر كاتيا وgive the slip إلى الإفلات، وحفظ فرع '+label+' كما في المصدر.')
c(1497,'<tab>'+k+'<br><br>','توحيد أتباع الطائفة بدل الطوائف وصقل عرض مساعدة كريست.')
c(1499,'<tab>عثرت على آنا. انهار بها سقف ملجأ يعود إلى ما قبل الحرب، وارتطم رأسها وفقدت الوعي بعض الوقت. ولحسن الحظ، يبدو أنها بخير الآن.<br><br><tab>في هذه الأثناء، طرأت مستجدات عند أورورا. يريدني العقيد أن أعود بأسرع ما يمكن...<br><br>','crashed through سقوط عبر سقف ملجأ لا مجرد اصطدام به؛ حفظ ضربة الرأس ومؤقتية الإغماء.')
c(1500,'<tab>لدينا خطة: نستولي على قافلة تجار النهر، ونستخدم زورق القطر للتسلل إلى الجسر. لكن القافلة لم تصل بعد، لذا أذن لي العقيد بإحضار عربة الركاب التي حدثتنا عنها كاتيا. وعلي أولًا أن أذهب إلى المحطة لأحضر عربة السكة الحديد الخاصة بكريست. لعل الوقت مناسب لاستكشاف المنطقة المحيطة.<br><br>','تمييز عربة السكة الحديد المحركة عن عربة الركاب، وصياغة إذن المهمة طبيعيًا.')
c(1502,'كان الأمر صعبًا، لكنني حصلت على عربة السكة الحديد. كانت المسوخ تملأ معبد سمكة القيصر. يبدو أن السكان كانوا يقدمون هنا قرابين بشرية لسمكة القيصر. لم أستطع ترك الأمر هكذا، فقتلت السمكة. آمل أن يفتح هذا أعينهم... على أي حال، وقد حصلت على عربة السكة الحديد، حان وقت إحضار عربة الركاب.<br><br>','توحيد سمكة القيصر ومعبدها، وحفظ فرع قتلها وحده والرجاء بصيغة الراوي المفرد.')
c(1503,'<tab>تمكنت من سرقة عربة الركاب بصمت. ستتسع مساحة المعيشة في أورورا كثيرًا حين أوصل العربة إليها.<br><br>','حفظ فرع السرقة الهادئة وتوضيح إحالة العربة دون حذف.')
c(1504,'<tab>اضطررت إلى قتال قطاع الطرق من أجل عربة الركاب، لكنها ستوفر مساحة معيشة أكبر بكثير في أورورا. يبقى أن أوصلها إليها أولًا.<br><br>','قاتلهم على ملكية العربة لا على سطحها؛ حفظ فرع القتال.')
c(1505,'<tab>أوصلت عربة الركاب إلى أورورا. وفي هذه الأثناء وصلت القافلة إلى الميناء، والإسبرطيون هناك بالفعل. علي أن ألتقي بآنا في الميناء ونخطط للاستيلاء على القافلة.<br><br>','تصحيح الاستيلاء والضمائر وزمن وجود الإسبرطيين الحالي وتوحيد عربة الركاب.')
c(1506,'<tab>التقيت بآنا في الميناء، وأطلعتني على الوضع. القافلة محروسة جيدًا، لكن إن أسرنا القبطان فسيستسلم الباقون. أيًا كان أسلوبي، سيدعمني الإسبرطيون. علي بلوغ غرفة قيادة زورق القطر.<br><br>','bridge على القارب غرفة قيادته لا جسر مادي، مع حفظ اختلاف طرق تنفيذ المهمة.')
end=' إذا سارت الأمور كما خططنا، فسنغادر هذا المكان قريبًا. هدفنا التالي حجرة التحكم بآلية الجسر.<br><br>'
c(1507,'<tab>استولينا على زورق القطر دون قتل أحد من أفراد القافلة. وباستخدامه، تسللت أنا وديوك إلى بلدة الجسر.'+end,'حفظ فرع عدم قتل أفراد القافلة وتصحيح ضمير زورق القطر المذكر.')
c(1508,'<tab>سقط بعض أفراد القافلة ضحايا، لكننا تمكنا من الاستيلاء على زورق القطر. وباستخدامه، تسللت أنا وديوك إلى بلدة الجسر.'+end,'حفظ فرع سقوط ضحايا القافلة منفصلًا عن فرع عدم القتل.')
c(1509,'على الجميع الحضور إلى مقصورة القيادة! بأقصى سرعة!','All hands طاقم القاطرة وbridge مقصورة قيادتها في هذا النداء، وon the double بأقصى سرعة.')
c(1510,'<ffx:fear_strong>الشيطان! لقد دهمنا الشيطان بنفسه!<ffx:fear_light>','upon us دهم المكان لا حرف علينا منفصل.')
c(1513,'<ffx:wonder>أتجمد منك شيء بعد يا عزيزي؟ تعال،<ffx:smile> لندفئك قليلًا!','تصحيح فاعل التجمد القسري وحفظ مزاح آنا دون اختراع عضو جسدي بعينه.')
c(1514,'<ffx:wonder>ما فرص وصولنا إلى يامانتو أحياء برأيك؟<ffx:sadness> لا يشغل بال أبي غير ذلك...','توحيد يامانتو وصياغة حديث الزوجين طبيعيًا.')
c(1515,'<ffx:sadness_light>كيف ينال العفو ويعود إلى المترو وحياته القديمة...','إصلاح الإحالة إلى حصول ميلر على العفو وتوحيد المترو دون تخمين مرجع الضمير الإنجليزي الغامض.')
c(1516,'<ffx:disgust>تلك الحياة التي طالما هربت منها.<ffx:sadness> وأنا التي... لم أصدقك قط...','And to think تعجب نادم لا مصدر وللتفكير؛ حفظ ندم آنا.')
c(1517,'<ffx:sadness_light>والآن أنظر إلى هذا الضباب،<ffx:wonder_light> وأفكر أنه ربما يخفي حياتنا الجديدة عنا...','تصحيح اسم إن المفقود وحفظ احتمال المستقبل خلف الضباب.')
c(1518,'<ffx:wonder>بالمناسبة، يفترض أن نقترب<ffx:smile_light> من الجسر قريبًا...','should توقع مكان وصول لا وجوب اقتراب مأمور به.')
c(1519,'<ffx:wonder_strong>اللعنة! موقد نار! أناس!<ffx:anger> هناك أناس! اضغط على المكابح! أطلق الإنذار!<ffx:anger_light>','campfire موقد لا نار مخيم معرف مجهول، وأوامر عاجلة للطاقم.')
c(1523,'<ffx:anger>تبًا!<ffx:anger_light>','Shit صيحة غضب لا اسم قذارة.')
c(1524,'<ffx:anger>الضباب اللعين!<ffx:sadness_light> يبدو أننا اخترقنا حاجزًا نصبه أحدهم!<ffx:wonder_light>','ran through اجتياز الحاجز لا المرور بجانبه.')
c(1525,'<ffx:wonder>من كانوا؟ هل رأيتم زيًا عسكريًا؟<ffx:wonder_light>','السؤال عن هوية المسلحين وزيهم لا أي زي المبتورة.')
c(1527,'<ffx:disgust_light>مجرد عجائز خرفين...<ffx:neutral>','old farts إهانة عجائز لا ريح قديمة.')
c(1528,'<ffx:smile_light>عجائز خرفون، هاه...<ffx:anger_light> هؤلاء مجرد حراس للنطاق الخارجي! كان يمكنهم وضع أي أحد هناك،<ffx:disgust> حتى النساء والأطفال!<ffx:neutral>','ربط الرد بالإهانة السابقة وتفسير حراسة النطاق العسكري المزعوم لا حارس محيط مفرد.')
(pathlib.Path(__file__).parent/'batch_1450.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
